/**
 * Adds Java rules to Xbase validation after type inference and linking.
 * Closure checks distinguish Java lambdas from the XJMethodReference subtype: references
 * share deferred functional typing, but have neither lambda parameters nor a lambda body.
 * Capture checks operate on linked writes so effectively final locals need no final keyword.
 *
 * @author Lorenzo Bettini
 */
public class JbaseValidator extends AbstractJbaseValidator {

	private static final XbasePackage XBASE_PACKAGE = XbasePackage.eINSTANCE;
	private static final JbasePackage JBASE_PACKAGE = JbasePackage.eINSTANCE;

	@Inject
	private JbaseNodeModelUtil nodeModelUtil;
	@Inject
	private JbaseModelUtil modelUtil;
	@Inject
	private ILogicalContainerProvider logicalContainerProvider;
	@Inject
	private IBatchTypeResolver batchTypeResolver;
	@Inject
	private JbaseSureReturnComputer sureReturnComputer;
	@Inject
	private IEarlyExitComputer earlyExitComputer;
	@Inject
	private JbaseInitializedVariableFinder initializedVariableFinder;
	@Inject
	private ProxyAwareUIStrings proxyAwareUIStrings;

	/**
	 * Removes only Xbase's six-parameter closure limit. A Java functional interface can have
	 * more parameters; its actual descriptor arity is still enforced by type computation.
	 */
	@Override
	public void checkClosureParams(final XClosure closure) {
		// Java functional interfaces do not impose Xbase's limit of six parameters.
	}

	/**
	 * Supplements Xbase inference with Java target, parameter and body restrictions.
	 * A generic interface such as Function<String, Integer> is valid, but a functional
	 * operation declaring its own type parameters cannot be implemented by a lambda.
	 * Explicit parameter types must match the descriptor; wildcard targets retain Xbase's
	 * ground-target inference instead of undergoing a literal identifier comparison.
	 *
	 * <p>A value block must return or throw on every path. A void expression body must be a
	 * statement expression: {@code () -> list.add("x")} can discard a result, while
	 * {@code () -> 1 + 2} cannot implement Runnable. References have their own helper and
	 * must be skipped even though their model extends XClosure.
	 */
	@Check
	public void checkJavaLambda(final XClosure closure) {
		if (closure instanceof XJMethodReference) {
			return;
		}
		var expectedType = getExpectedType(closure);
		var operation = expectedType == null ? null
			: getServices().getFunctionTypes().findImplementingOperation(expectedType);
		if (operation == null || !expectedType.isInterfaceType()
				|| !operation.getTypeParameters().isEmpty()) {
			error("A lambda expression requires a functional interface target type",
				closure, null, INVALID_LAMBDA);
			return;
		}
		var functionType = expectedType.tryConvertToFunctionTypeReference(expectedType.isRawType());
		var parameters = closure.getDeclaredFormalParameters();
		if (parameters.stream().anyMatch(parameter -> parameter.getParameterType() == null)
				&& parameters.stream().anyMatch(parameter -> parameter.getParameterType() != null)) {
			error("Cannot mix 'var' and explicitly typed lambda parameters",
				closure, null, INVALID_LAMBDA);
		}
		var parameterTypes = functionType.getParameterTypes();
		for (var i = 0; i < Math.min(parameters.size(), parameterTypes.size()); i++) {
			var declaredType = parameters.get(i).getParameterType();
			if (declaredType != null
					&& expectedType.getTypeArguments().stream().noneMatch(type -> type.isWildcard())
					&& !toLightweightTypeReference(declaredType).getIdentifier()
						.equals(parameterTypes.get(i).getIdentifier())) {
				error("Lambda parameter type must match the functional interface parameter type",
					parameters.get(i), null, INVALID_LAMBDA);
			}
		}
		var body = closure.getExpression();
		if (body instanceof XBlockExpression
				&& !functionType.getReturnType().isPrimitiveVoid()
				&& !earlyExitComputer.isEarlyExit(body)) {
			errorMissingReturnStatement(body);
		}
		if (!(body instanceof XBlockExpression)
				&& functionType.getReturnType().isPrimitiveVoid()
				&& !isStatementExpression(body)) {
			error("A void lambda body must be a statement expression", closure, null, INVALID_LAMBDA);
		}
	}

	/**
	 * Recognizes the Java expression forms whose result may be discarded by a void lambda.
	 * A feature call must denote an operation: reading a field is not a statement expression.
	 */
	private boolean isStatementExpression(final XExpression body) {
		return body instanceof XAssignment || body instanceof XConstructorCall
			|| body instanceof XPostfixOperation
			|| body instanceof XBinaryOperation binary && binary.isReassignFirstArgument()
			|| (body instanceof XFeatureCall || body instanceof XMemberFeatureCall)
				&& ((XAbstractFeatureCall) body).getFeature() instanceof JvmOperation;
	}

	/**
	 * Checks external locals and formal parameters after all of their uses have been linked.
	 * A reference receiver is read immediately, so {@code text::trim} does not require text
	 * to remain effectively final. Skipping its model node still finds a real outer lambda
	 * in {@code () -> text::trim}, where the external local is captured.
	 */
	@Check
	public void checkCapturedLocal(final XAbstractFeatureCall call) {
		var feature = call.getFeature();
		if (!(feature instanceof XVariableDeclaration || feature instanceof JvmFormalParameter)) {
			return;
		}
		var closure = EcoreUtil2.getContainerOfType(call, XClosure.class);
		while (closure instanceof XJMethodReference) {
			closure = EcoreUtil2.getContainerOfType(closure.eContainer(), XClosure.class);
		}
		if (closure == null || EcoreUtil.isAncestor(closure, feature)) {
			return;
		}
		var writes = XbaseUsageCrossReferencer.find(feature, EcoreUtil.getRootContainer(closure))
			.stream().map(Setting::getEObject)
			.filter(this::isLocalWrite).toList();
		if (!writes.isEmpty() && !isEffectivelyFinal(feature, writes)) {
			error("Local variable " + feature.getSimpleName()
				+ " must be final or effectively final when captured by a lambda",
				call, XBASE_PACKAGE.getXAbstractFeatureCall_Feature(), NON_EFFECTIVELY_FINAL_CAPTURE);
		}
	}

	/**
	 * Recognizes first assignments to a blank local, including opposite if/else branches.
	 * An initialized local or parameter cannot be written again, and even a blank local
	 * cannot acquire repeated or potentially repeating writes. Definite assignment is
	 * checked separately, so recognizing an exclusive first assignment is not sufficient
	 * by itself to make every subsequent read valid.
	 */
	private boolean isEffectivelyFinal(final EObject feature, final List<EObject> writes) {
		if (!(feature instanceof XVariableDeclaration variable) || variable.getRight() != null) {
			return false;
		}
		var scope = EcoreUtil2.getContainerOfType(variable, XBlockExpression.class);
		for (var write : writes) {
			if (!(write instanceof XAssignment) || canRepeatWrite(write, scope)) {
				return false;
			}
			for (var other : writes) {
				if (write != other && !areExclusiveWrites(write, other, scope)) {
					return false;
				}
			}
		}
		return true;
	}

	/**
	 * Detects assignments that may run repeatedly inside a closure or loop.
	 * A basic for initializer runs once and is exempt; its body and update are not.
	 * Likewise, an enhanced-for iterable expression is outside the repeated body.
	 */
	private boolean canRepeatWrite(final EObject write, final EObject scope) {
		var child = write;
		for (var parent = child.eContainer(); parent != scope; parent = child.eContainer()) {
			if (parent instanceof XClosure || parent instanceof XAbstractWhileExpression
					|| parent instanceof XBasicForLoopExpression loop
						&& !loop.getInitExpressions().contains(child)
					|| parent instanceof XForLoopExpression loop && loop.getEachExpression() == child) {
				return true;
			}
			child = parent;
		}
		return false;
	}

	/** Tests whether the writes are in opposite branches of an enclosing if/else. */
	private boolean areExclusiveWrites(final EObject first, final EObject second,
			final EObject scope) {
		for (var parent = first.eContainer(); parent != scope; parent = parent.eContainer()) {
			if (parent instanceof XIfExpression conditional
					&& (EcoreUtil.isAncestor(conditional.getThen(), first)
						&& EcoreUtil.isAncestor(conditional.getElse(), second)
					|| EcoreUtil.isAncestor(conditional.getElse(), first)
						&& EcoreUtil.isAncestor(conditional.getThen(), second))) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Counts rebinding, increment/decrement and compound assignment as writes to a local.
	 * {@code values[0] = 1} writes an array element, not the captured values variable.
	 */
	private boolean isLocalWrite(final EObject reference) {
		return reference instanceof XAssignment && !(reference instanceof XJAssignment)
			|| reference.eContainer() instanceof XPostfixOperation
			|| reference.eContainer() instanceof XBinaryOperation binary
				&& binary.isReassignFirstArgument() && binary.getLeftOperand() == reference;
	}

	@Override
	protected void checkAssignment(final XExpression expression, final EStructuralFeature feature,
			final boolean simpleAssignment) {
		if (expression instanceof XJArrayAccess) {
			// it means that we're accessing an array element, thus the
			// typical checks on an assignment (i.e., whether the variable is final,
			// or whether it's an abstract feature call) should not be performed
			return;
		}
		if (expression instanceof XAbstractFeatureCall call
				&& call.getFeature() instanceof JvmFormalParameter parameter) {
			// all parameters are considered NOT final by default
			var originalParam = modelUtil.getOriginalParam(parameter);
			if (originalParam == null || !originalParam.isFinal()) {
				return;
			}
		}
		super.checkAssignment(expression, feature, simpleAssignment);
	}

	/**
	 * In case of an additional variable declaration we must use the container of
	 * the containing variable declaration, otherwise additional variables will always be
	 * detected as unused; similarly if the container is a semicolon statement which
	 * contains a variable declaration
	 */
	@Override
	protected boolean isLocallyUsed(final EObject target, final EObject containerToFindUsage) {
		if (target instanceof XJAdditionalXVariableDeclaration
				&& containerToFindUsage instanceof XVariableDeclaration) {
			return isLocallyUsed(target, containerToFindUsage.eContainer());
		}
		if (containerToFindUsage instanceof XJSemicolonStatement) {
			return isLocallyUsed(target, containerToFindUsage.eContainer());
		}
		if (target instanceof XVariableDeclaration variable
				&& variable.getType() instanceof JvmGenericArrayTypeReference
				&& !super.isLocallyUsed(target, containerToFindUsage)
				// assigning to one of its elements should mark it as used
				&& XbaseUsageCrossReferencer.find(target, containerToFindUsage).stream()
						.anyMatch(reference -> reference.getEObject() instanceof XJAssignment)) {
			return true;
		}
		return super.isLocallyUsed(target, containerToFindUsage);
	}

	@Check
	public void checkContinue(final XJContinueStatement st) {
		checkBranchingStatementInternal(st, "a loop", "continue",
			XAbstractWhileExpression.class, XBasicForLoopExpression.class);
	}

	@Check
	public void checkBreak(final XJBreakStatement st) {
		checkBranchingStatementInternal(st, "a loop or a switch", "break",
			XAbstractWhileExpression.class, XBasicForLoopExpression.class, XSwitchExpression.class);
	}

	/**
	 * Searches for a legal loop/switch target without crossing a closure boundary.
	 * For example, a lambda inside an outer for cannot continue that outer loop; it must
	 * contain its own applicable loop. Semicolon wrappers do not introduce a boundary.
	 */
	@SafeVarargs
	private final void checkBranchingStatementInternal(final XJBranchingStatement st,
			final String errorDetails, final String instruction,
			final Class<? extends EObject>... validContainers) {
		var container = st.eContainer();
		while (container != null) {
			if (container instanceof XClosure) {
				break;
			}
			for (var validContainer : validContainers) {
				if (validContainer.isInstance(container)) {
					return;
				}
			}
			container = container.eContainer();
		}
		error(instruction + " cannot be used outside of " + errorDetails,
			st, null, INVALID_BRANCHING_STATEMENT);
	}

	@Check
	public void checkMissingSemicolon(final XJSemicolonStatement e) {
		if (e.getSemicolon() == null) {
			errorMissingSemicolon(e.getExpression());
		}
	}

	@Check
	public void checkMissingSemicolon(final XImportDeclaration e) {
		checkMissingSemicolonInternal(e);
	}

	@Check
	public void checkTryWithResources(final XJTryWithResourcesStatement e) {
		var resourceDeclarations = e.getResources().stream()
			.filter(XJTryWithResourcesVariableDeclaration.class::isInstance)
			.map(XJTryWithResourcesVariableDeclaration.class::cast).toList();
		if (resourceDeclarations.isEmpty()) {
			error("Syntax error on token \"(\", Resources expected after this token",
				e, JBASE_PACKAGE.getXJTryWithResourcesStatement_OpenParenthesis(), MISSING_RESOURCES);
		} else {
			// in the last declaration the ';' is optional
			for (var i = 0; i < resourceDeclarations.size() - 1; i++) {
				var resource = resourceDeclarations.get(i);
				if (resource.getSemicolon() == null) {
					errorMissingSemicolon(resource);
				}
			}
		}
	}

	@Check
	public void checkAutoCloseableResource(final XJTryWithResourcesVariableDeclaration e) {
		var declaredType = getActualType((JvmIdentifiableElement) e);
		var autoCloseable = new StandardTypeReferenceOwner(getServices(), e)
			.toLightweightTypeReference(getServices().getTypeReferences()
				.getTypeForName(AutoCloseable.class, e));
		if (!autoCloseable.isAssignableFrom(declaredType)) {
			error("The resource type " + declaredType + " does not implement java.lang.AutoCloseable",
				e, XBASE_PACKAGE.getXVariableDeclaration_Type(), NOT_AUTO_CLOSEABLE);
		}
	}

	@Check
	public void checkVarDeclaration(final XJVariableDeclaration declaration) {
		if (declaration.getType() != null) {
			return;
		}
		if (!declaration.getAdditionalVariables().isEmpty()) {
			error("'var' is not allowed in a compound declaration", declaration,
				XBASE_PACKAGE.getXVariableDeclaration_Name(), INVALID_VAR_DECLARATION);
		}
		final var initializer = declaration.getRight();
		if (initializer == null) {
			error("Cannot infer type for local variable without an initializer", declaration,
				XBASE_PACKAGE.getXVariableDeclaration_Name(), INVALID_VAR_DECLARATION);
		} else if (getActualType(initializer).isAny()) {
			error("Cannot infer type for local variable initialized to 'null'", declaration,
				XBASE_PACKAGE.getXVariableDeclaration_Right(), INVALID_VAR_DECLARATION);
		} else if (initializer instanceof XJArrayLiteral) {
			error("Array initializer needs an explicit target type", declaration,
				XBASE_PACKAGE.getXVariableDeclaration_Right(), INVALID_VAR_DECLARATION);
		}
	}

	private void checkMissingSemicolonInternal(final EObject e) {
		if (!nodeModelUtil.hasSemicolon(e)) {
			errorMissingSemicolon(e);
		}
	}

	private void errorMissingSemicolon(final EObject e) {
		error("Syntax error, insert \";\" to complete Statement", e, null, MISSING_SEMICOLON);
	}

	@Check
	public void checkMissingParentheses(final XFeatureCall call) {
		checkMissingParenthesesInternal(call, call.isExplicitOperationCall());
	}

	@Check
	public void checkMissingParentheses(final XMemberFeatureCall call) {
		checkMissingParenthesesInternal(call, call.isExplicitOperationCall());
	}

	@Check
	public void checkMissingParentheses(final XConstructorCall call) {
		if (!call.isExplicitConstructorCall()) {
			error("Syntax error, insert \"()\" to complete Expression", call,
				XBASE_PACKAGE.getXConstructorCall_Constructor(), MISSING_PARENTHESES);
		}
	}

	@Check
	public void checkConstructorCallRawType(final XJConstructorCall call) {
		if (modelUtil.isRawType(call)) {
			var constructorType = (JvmType) call.getConstructor().eContainer();
			var message = new StringBuilder(64);
			message.append(constructorType.getSimpleName());
			message.append(" is a raw type. References to generic type ");
			message = proxyAwareUIStrings.appendTypeSignature(constructorType, message);
			message.append(" should be parameterized");
			warning(message.toString(), XBASE_PACKAGE.getXConstructorCall_Constructor(),
				IssueCodes.RAW_TYPE);
		}
	}

	@Check
	public void checkArrayConstructor(final XJArrayConstructorCall cons) {
		var arrayLiteral = cons.getArrayLiteral();
		var dimensionExpressions = cons.getIndexes();
		if (dimensionExpressions.isEmpty() && arrayLiteral == null) {
			error("Constructor must provide either dimension expressions or an array initializer",
				cons, null, ARRAY_CONSTRUCTOR_EITHER_DIMENSION_EXPRESSION_OR_INITIALIZER);
		} else if (!dimensionExpressions.isEmpty() && arrayLiteral != null) {
			error("Cannot define dimension expressions when an array initializer is provided",
				cons, null, ARRAY_CONSTRUCTOR_BOTH_DIMENSION_EXPRESSION_AND_INITIALIZER);
		} else {
			var dimensionsAndIndexes = modelUtil.arrayDimensionIndexAssociations(cons);
			var foundEmptyDimension = false;
			for (var dimension : dimensionsAndIndexes) {
				if (dimension == null) {
					foundEmptyDimension = true;
				} else if (foundEmptyDimension) {
					error("Cannot specify an array dimension after an empty dimension", dimension, null,
						ARRAY_CONSTRUCTOR_DIMENSION_EXPRESSION_AFTER_EMPTY_DIMENSION);
					return;
				}
			}
		}
	}

	@Check
	public void checkCharacterLiteral(final XJCharLiteral c) {
		var length = c.getValue().length();
		if (length > 1) {
			error("Invalid character constant", c, null, INVALID_CHARACTER_CONSTANT);
		}
	}

	private void checkMissingParenthesesInternal(final XAbstractFeatureCall call,
			final boolean explicitOpCall) {
		// length for arrays is OK without parentheses
		if (call.getFeature() instanceof JvmOperation && !explicitOpCall
				&& !JbaseOperatorMapping.ARRAY_LENGTH.equals(call.getFeature().getSimpleName())) {
			error("Syntax error, insert \"()\" to complete method call", call,
				XBASE_PACKAGE.getXAbstractFeatureCall_Feature(), MISSING_PARENTHESES);
		}
	}

	@Check
	public void checkVarArgComesLast(final XJJvmFormalParameter param) {
		if (param.isVarArgs() || param.eContainer() instanceof XClosure
				&& param.getParameterType() != null
				&& nodeModelUtil.getProgramText(param.getParameterType()).endsWith("...")) {
			var params = (List<?>) param.eContainer().eGet(param.eContainingFeature());
			if (param != params.getLast()) {
				error("A vararg must be the last parameter.", param,
					JBASE_PACKAGE.getXJJvmFormalParameter_VarArgs(), INVALID_USE_OF_VAR_ARGS);
			}
		}
	}

	/**
	 * This can be explicitly called on an XBlockExpression which represents
	 * the body of an inferred JvmOperation; it will check that,
	 * if the corresponding Java method is not void, a return
	 * is specified in all possible paths.
	 */
	protected void checkMissingReturn(final XBlockExpression body) {
		var jvmOperation = logicalContainerProvider.getLogicalContainer(body);
		var types = batchTypeResolver.resolveTypes(body);
		if (types.getActualType(jvmOperation).isPrimitiveVoid()) {
			return;
		}
		var expressions = body.getExpressions();
		var lastExpression = expressions.isEmpty() ? null : expressions.getLast();
		if (lastExpression == null) {
			errorMissingReturnStatement(body);
			return;
		}
		if (!sureReturnComputer.isSureReturn(lastExpression)) {
			errorMissingReturnStatement(lastExpression);
		}
	}

	/**
	 * This can be explicitly called on an XBlockExpression which represents
	 * the body of an inferred JvmOperation; it will check that
	 * variable references refer to variables that are surely initialized,
	 * according to the Java semantics.  This should be called only on
	 * top block expressions, as stated above.
	 */
	protected void checkVariableInitialization(final XBlockExpression e) {
		initializedVariableFinder.detectNotInitialized(e, ref -> error(
			"The local variable " + ref + " may not have been initialized", ref,
			XBASE_PACKAGE.getXAbstractFeatureCall_Feature(), NOT_INITIALIZED_VARIABLE));
	}

	private void errorMissingReturnStatement(final XExpression e) {
		var source = e instanceof XJSemicolonStatement statement ? statement.getExpression() : e;
		error("Missing return", source, null, MISSING_RETURN);
	}

	/**
	 * Avoids issues that are specific to Xbase, like the warning when you
	 * compare to null with '==' instead of '==='
	 * (see https://github.com/LorenzoBettini/jbase/issues/72)
	 */
	@Override
	protected void addIssue(final String message, final EObject source,
			final EStructuralFeature feature, final int index, final String issueCode,
			final String... issueData) {
		if (IssueCodes.EQUALS_WITH_NULL.equals(issueCode)) {
			return;
		}
		super.addIssue(message, source, feature, index, issueCode, issueData);
	}
}
